"""Build a self-contained FI02 GLB preview with actual game actors, no game loop/save."""
from pathlib import Path
import re,base64,json
ROOT=Path(__file__).resolve().parents[2];A=ROOT/'assets/maps/fi02-record-lane';OUT=ROOT/'dist/fi02-island-review.html'
files=re.findall(r'<script src="([^"]+)"',(ROOT/'index.html').read_text());files=files[:files.index('src/game/05-ui.js')]
page='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FI02 前街唱片巷｜模型預覽</title><style>*{box-sizing:border-box}body{margin:0;background:#edf1f5;color:#24384f;font:16px/1.55 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:16px}h1{margin:0;font-size:24px}p{margin:6px 0}button,select{font:inherit;min-height:44px;margin:4px 4px 4px 0;padding:6px 12px;background:white;border:1px solid #8294af;border-radius:5px;color:inherit}canvas{width:100%;height:70vh;display:block;background:white;touch-action:none}#status{min-height:50px;font-size:14px}</style><main><h1>前街唱片巷 · FI02</h1><p>已批准概念的第一張3D樣板。角色沿島走動；可按地面指定位置。此為模型／導航預覽，不是正式戰鬥關卡，不讀寫存檔。</p><div><select id="view" aria-label="視角"><option value="iso">概念斜視</option><option value="game">遊戲鏡頭方向</option><option value="top">頂視</option><option value="front">正面</option><option value="right">右側</option></select><select id="mode" aria-label="模型模式"><option value="color">純色模型</option><option value="white">白模</option></select><button id="actors">隱藏角色</button><button id="walk">暫停走動</button><button id="nav">顯示可走區</button><label>縮放 <input id="zoom" aria-label="縮放" type="range" min="1" max="3" step="0.1" value="1"></label></div><canvas id="map" aria-label="浮島模型互動預覽"></canvas><p id="status" role="status">載入模型…</p></main>'''
page+='''<script>const reviewStorage=(()=>{const m=new Map();return{getItem:k=>m.get(String(k))??null,setItem:(k,v)=>m.set(String(k),String(v)),removeItem:k=>m.delete(String(k)),clear:()=>m.clear()}})();</script>'''
for f in files:
 s=re.sub(r'\b(?:localStorage|sessionStorage)\b','reviewStorage',(ROOT/f).read_text());page+='<script>\n'+s+'\n</script>'
page+='<script>const FI02_LAYOUT='+json.dumps(json.loads((A/'layout.json').read_text()),ensure_ascii=False)+';\n'
for key,file in [('fi02_color','fi02-record-lane.glb'),('fi02_white','fi02-blockout.glb')]:page+='EQUIPMENT_COMPLETION_GLB.'+key+'='+json.dumps(base64.b64encode((A/file).read_bytes()).decode())+';\n'
page+='</script><script>'+ (ROOT/'tools/maps/fi02-layout-runtime.js').read_text()+'</script><script>'+ (ROOT/'tools/maps/fi02-review-runtime.js').read_text()+'</script></html>'
OUT.write_text(page);print('Built',OUT,'bytes',OUT.stat().st_size)
